"""Independent counters, actual resource and latency checks. No inference."""
import math
import contractnli_io as I
import contractnli_metrics as M
VARIABLE_COUNTER_KEYS=('BGE_forward_calls_attempted','BGE_forward_calls_completed','Python_literal_loopback_capability_binds_allowed')

def execution_audit(raw,plan,expected_source,project):
 lifecycle=lifecycle_audit(raw);model_audit=model_runtime_audit(raw);expected=I.load_ref(expected_source,project);I.require(expected['epoch']==40 and expected['kind']==I.KIND,'FROZEN_E40_COUNTER_SOURCE_REQUIRED');fixed=expected['dev'];I.require(plan['expected_operation_counters']['dev']==fixed,'PLAN_COUNTERS_DIFFER_FROM_REVIEWED_SOURCE');c=raw['counters']
 for key,want in fixed.items():I.require(type(c[key])is int and c[key]==want,'ACTUAL_COUNTER_MISMATCH:'+key)
 I.require(c['BGE_forward_calls_attempted']==c['BGE_forward_calls_completed']and type(c['BGE_forward_calls_completed'])is int and c['BGE_forward_calls_completed']>0,'REAL_COMPLETED_BGE_FORWARDS_REQUIRED');I.require(c['BGE_forward_calls_completed']==sum((len(r['source_unit_ids'])+7)//8+1 for r in raw['cases']),'EXACT_REAL_BGE_BATCH_COUNT_REQUIRED');I.require(type(c['Python_literal_loopback_capability_binds_allowed'])is int and c['Python_literal_loopback_capability_binds_allowed']in[0,1],'BOUNDED_LITERAL_LOOPBACK_ONLY');I.require(set(c)==set(fixed)|set(VARIABLE_COUNTER_KEYS),'UNDECLARED_OR_MISSING_OPERATION_COUNTERS')
 wall=raw['wall_seconds'];I.require(M.finite(wall)and 0<wall<=600,'ACTUAL_WHOLE_BATCH_MAX600_SECONDS_REQUIRED');resources=raw['resources'];I.require(resources['cpu_affinity']==[0,1]and resources['torch_num_threads']==2 and resources['torch_num_interop_threads']==1,'ACTUAL_TWO_CPU_THREAD_RESOURCE_LIMIT_REQUIRED')
 for name in ['user_seconds','system_seconds','max_rss_kib']:I.require(M.finite(resources[name])and resources[name]>=0,'ACTUAL_RESOURCE_OBSERVATION_REQUIRED:'+name)
 by_arm={}
 for arm in M.ARMS:
  timings=[r['readouts'][arm]['timing']for r in raw['cases']];I.require(len(timings)==12,'FULL_TIMING_DENOMINATOR_REQUIRED');keys={'pair_tokenization_seconds','NNI_forward_seconds','reader_total_seconds'};extras={'context_order_seconds','native_query_seconds','scope'};I.require(all(set(v)==keys|extras for v in timings),'FROZEN_READOUT_LATENCY_COMPONENTS_REQUIRED');out={}
  for case,v in zip(raw['cases'],timings):I.require(v['context_order_seconds']==case['context_order_seconds']and v['native_query_seconds']==case['native_query_seconds']and type(v['scope'])is str,'SHARED_CONTEXT_QUERY_LATENCY_BINDING_REQUIRED')
  for key in sorted(keys):
   vals=[v[key]for v in timings];I.require(all(M.finite(x)and x>=0 for x in vals),'FINITE_ACTUAL_TIMING_REQUIRED');out[key]={'N':12,'p50':M.quantile(vals,.5),'p95':M.quantile(vals,.95),'sum':math.fsum(vals),'scope':'Per actual measured readout component. Shared BGE/native/model initialization and whole batch are separate; not publisher end-to-end latency.'}
  for v in timings:I.require(v['reader_total_seconds']+1e-6>=v['pair_tokenization_seconds']+v['NNI_forward_seconds'],'READOUT_TOTAL_COMPONENT_INTEGRITY')
  by_arm[arm]=out
 case_spans=[];component_sums=[]
 for case in raw['cases']:
  r=case['pipeline_timing'];start=r['source_preparation_started_monotonic_seconds'];end=r['all_readouts_completed_monotonic_seconds'];span=r['batch_case_span_seconds'];component=r['evidence_preparation_component_sum_seconds'];I.require(all(M.finite(x)and x>=0 for x in[start,end,span,component])and end>=start and abs((end-start)-span)<=1e-6 and span<=wall+1e-6 and type(r['scope'])is str,'ACTUAL_BATCH_CASE_SPAN_TIMING_INTEGRITY');case_spans.append(span);component_sums.append(component)
 pipeline={'N':12,'batch_case_span_seconds':{'p50':M.quantile(case_spans,.5),'p95':M.quantile(case_spans,.95)},'evidence_preparation_component_sum_seconds':{'p50':M.quantile(component_sums,.5),'p95':M.quantile(component_sums,.95)},'scope':'Actual percase BGE start to final fourth readout; includes othercase queue/shared modelinit/nativebatch waits; excludes initialsharedBGEinit. Not isolated case or publisher latency. Components remain distinct and no concurrent peakRSS is inferred.'}
 return {'checks_passed':True,'reader_lifecycle_audit':lifecycle,'model_runtime_audit':model_audit,'fixed_counters_checked':len(fixed),'actual_counters':c,'wall_seconds_including_initialization_and_cleanup':wall,'actual_resources':resources,'latency_by_arm':by_arm,'batch_case_pipeline_latency':pipeline,'no_total_or_parallel_memory_inferred_from_summed_RSS':True}
def lifecycle_audit(raw):
 rows=raw['reader_lifecycle'];I.require(type(rows)is list and len(rows)==10,'TEN_OBSERVED_READER_LIFECYCLE_EVENTS_REQUIRED');events=['MODEL_PHASE_START','MODEL_INITIALIZATION_COMPLETED','MODEL_READOUTS_COMPLETED','MODEL_UNLOAD_BEFORE','MODEL_UNLOAD_AFTER_GC'];last=-math.inf
 for j,tag in enumerate(['b354','tasksource']):
  global_counts=[0,0,12,12,12]if tag=='b354'else[12,12,48,48,48];profile_counts=[0,0,12,12,12]if tag=='b354'else[0,0,36,36,36]
  for i,event in enumerate(events):
   r=rows[j*5+i];I.require(r['model_tag']==tag and r['event']==event and type(r['global_readouts_completed'])is int and r['global_readouts_completed']==global_counts[i]and type(r['profile_readouts_completed'])is int and r['profile_readouts_completed']==profile_counts[i],'ACTUAL_SEQUENTIAL_MODEL_LIFECYCLE_MISMATCH');stamp=r['monotonic_seconds'];I.require(M.finite(stamp)and stamp>=last,'ACTUAL_ORDERED_LIFECYCLE_TIMESTAMPS_REQUIRED');last=stamp
   if event=='MODEL_READOUTS_COMPLETED':I.require(r['model_state_unchanged']['unchanged']is True and r['model_state_unchanged']['classifier_manifest']==raw['model_runtime_receipts'][tag]['classifier_manifest'],'FROZEN_MODEL_STATE_CHANGED')
   if event=='MODEL_UNLOAD_AFTER_GC':I.require(all(r[k]is True for k in ['reader_weakref_dead','model_weakref_dead','tokenizer_weakref_dead']),'OBSERVED_MODEL_TOKENIZER_DISPOSAL_REQUIRED')
 return {'checks_passed':True,'events_observed':10,'model_profiles_disposed':['b354','tasksource'],'no_model_coexistence_in_observed_lifecycle':True}

def model_runtime_audit(raw):
 expected={'b354':(435064835,'c03cd208bf920b4fbbb182a0535859a566e8acc3477d2b536bf87b769978524b','F16'),'tasksource':(435064835,'534780ea5d1f76d22be966d10de67cf2690ec25010aeb4b607d4aadcd2649ebc','F32')};receipts=raw['model_runtime_receipts'];I.require(set(receipts)==set(expected),'BOTH_ACTUAL_MODEL_RUNTIME_RECEIPTS_REQUIRED')
 for tag,(count,weight_sha,source_dtype)in expected.items():
  r=receipts[tag];I.require(r['model_class']=='DebertaV2ForSequenceClassification'and r['learned_parameters']==count and type(r['learned_parameters'])is int and r['weights_sha256']==weight_sha and r['CPU_FP32']is True and r['meta_tensors_remaining']==0 and r['source_parameter_dtype']==source_dtype and r['compute_dtype']=='F32'and r['all_source_values_preserved_exactly']is True and r['loading_missing_keys']==r['loading_unexpected_keys']==[]and r['no_training_or_classifier_reinitialization']is True and r['actual_model_warmup_forwards']==0 and r['tokenizer_class']=='DebertaV2TokenizerFast'and r['pair_special_tokens']==3 and r['attention']=='eager','EXACT_FROZEN_CPU_MODEL_RUNTIME_REQUIRED:'+tag)
 return {'checks_passed':True,'actual_model_profiles':['b354','tasksource'],'new_model_strength_claim':False,'lineage_and_eligibility':'HOLD'}

SUPERVISOR_INVARIANT_KEYS=('raw_forecasts_complete_without_gold','exact_frozen_operation_counts','forbidden_operation_counts_zero','worker_errors_empty','offline_policy_closed','all48_unique_forecasts','all48_required','native_child_closed','both_readers_disposed_in_order','all_forecasts_closed_before_gold','gold_not_decoded','whole_worker_CPU_guard_before_exec')
def supervisor_qualification(execution,completion,raw,refs,physical,project,dispatch):
 """Qualification differs from closure: a stopped failed run is not accepted."""
 I.require(execution['status']=='WORKER_COMPLETED','SUPERVISOR_EXECUTION_NOT_QUALIFIED');wall=execution['wall_seconds_including_init_cleanup'];I.require(M.finite(wall)and 0<wall<=600,'SUPERVISOR_WHOLE_INIT_CLEANUP_WALL_EXCEEDS600_OR_INVALID')
 I.require(type(execution['exit_code'])is int and execution['exit_code']==0 and execution['launcher_error']is None and execution['cleanup_errors']==[]and execution['stdout_stderr_capture_completed']is True and execution['uncertain_start']is False and execution['owned_live_processes_closed']is True and execution['owned_live_group_members']==[]and execution['source_plan_unchanged']is True,'SUPERVISOR_COMPLETION_ERROR_OR_UNCERTAINTY')
 invariants=execution['raw_closure_invariants'];I.require(type(invariants)is dict and set(invariants)==set(SUPERVISOR_INVARIANT_KEYS)and all(v is True for v in invariants.values()),'SUPERVISOR_RAW_COMPLETION_INVARIANTS_NOT_ALL_TRUE')
 I.require(execution['raw']==refs['raw']and execution['raw_sha256']==refs['raw']['sha256']and execution['raw_bytes']==refs['raw']['bytes']and execution['raw_operation_counters_source']=='raw.json'and execution['operation_counts_complete']is True and execution['raw_operation_counters']==raw['counters'],'SUPERVISOR_FINAL_RAW_CAPTURE_MISMATCH')
 evidence=physical['evidence'];I.require(execution['dispatch_attempt']==refs['dispatch']and execution['dispatch_reservation']==evidence['reservation'],'SUPERVISOR_DISPATCH_RESERVATION_MISMATCH');cpu=I.load_ref(execution['worker_cpu_guard_preexec_artifact'],project);I.require(cpu==execution['worker_cpu_guard_preexec']and cpu['status']=='CPU_GUARD_INSTALLED_BEFORE_EXEC'and cpu['CPU_affinity']==[0,1]and cpu['actual_proc_status']['NoNewPrivs']=='1'and cpu['actual_proc_status']['Seccomp']=='2','SUPERVISOR_CPU_PREEXEC_INVARIANT_MISMATCH')
 I.require(physical['physical_supervisor_absent']is False and physical['observed_supervisor_state']=='Z'and physical['supervisor_exit_status_source']=='PROC_STAT_FIELD52_EXACT_STABLE_ZOMBIE'and type(physical['observed_supervisor_exit_wait_status'])is int and physical['observed_supervisor_exit_wait_status']==0,'ACTUAL_SUPERVISOR_EXIT_STATUS_ZERO_REQUIRED_NO_ABSENT_INFERENCE')
 observed=physical['observed_closed_by_monotonic_seconds'];start=dispatch['dispatch_monotonic_seconds'];I.require(M.finite(observed)and M.finite(start)and start>0 and 0<=observed-start<=600 and wall<=observed-start,'OBSERVED_FULL_SUPERVISOR_BOUND_INCLUDING_FINAL_FSYNC_REQUIRED')
 I.envelope(completion);I.require(completion['status']=='SUPERVISOR_ABOUT_TO_EXIT'and completion['plan_sha256']==execution['plan_sha256']and completion['execution_sha256']==refs['execution']['sha256']and completion['execution_status']=='WORKER_COMPLETED'and type(completion['intended_exit_code'])is int and completion['intended_exit_code']==0 and completion['exit_code_observed_by_root']is False and completion['requires_external_physical_supervisor_closure']is True and completion['supervisor_identity']==execution['supervisor_identity']==physical['supervisor_identity'],'SUPERVISOR_COMPLETION_INTENTION_CHAIN_MISMATCH')
 return {'checks_passed':True,'execution_status':'WORKER_COMPLETED','observed_worker_exit_code':0,'recorded_wall_seconds_including_init_cleanup':wall,'recorded_wall_scope':'Launcher sample after owned cleanup; external stable-zombie exit-status observation and post-fence monotonic timestamp additionally include final metadata fsync and full supervisor closure.','supervisor_intended_exit_code':0,'supervisor_exit_code_observed_by_root':False,'supervisor_exit_status_independently_observed_from_proc_stat':True,'observed_supervisor_exit_wait_status':0,'supervisor_exit_status_source':'PROC_STAT_FIELD52_EXACT_STABLE_ZOMBIE','observed_full_supervisor_bound_seconds':observed-start,'physical_supervisor_closed':physical['physical_supervisor_closed'],'physical_supervisor_absent':physical['physical_supervisor_absent'],'observed_supervisor_state':physical['observed_supervisor_state'],'all12_raw_completion_invariants_true':True}
